def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))

    def extend_endpoint(r, c, dr, dc, color):
        # An orthogonal same-color connection means this end points back into the object.
        for ar, ac in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] == color:
                return
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
            out[rr][cc] = color
            rr += dr
            cc += dc

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                line = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    line.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(line) >= 2:
                    r0, c0 = line[0]
                    r1, c1 = line[-1]
                    extend_endpoint(r0, c0, -dr, -dc, color)
                    extend_endpoint(r1, c1, dr, dc, color)

    return out
